inhalt.api:
Alles unten steht in src/lib/api.ts, dem einzigen Datenbank-Zugang. Jede Funktion wirft bei Fehlern Error(tg('fehler.<schluessel>', {grund: errText(e)})). "Nichts" und "Fehler" sind verschieden: null bzw. leere Liste heißt "nicht vorhanden", ein Fehler wirft.

NEUE TYPEN (src/lib/types.ts)
export type GrundrissArt = 'wohnung' | 'alte_wohnung' | 'keller' | 'lager' | 'sonstiges'
export interface GrundrissKopf { id: string; project_id: string; name: string; art: GrundrissArt; standard_hoehe_cm: number; sort: number; version: number; updated_at: string }
export interface Wand { id: string; grundriss_id: string; x0: number; y0: number; x1: number; y1: number; dicke_cm: number; hoehe_cm: number | null; farbe: string | null }
export interface Oeffnung { id: string; grundriss_id: string; wand_id: string; art: 'tuer' | 'fenster'; abstand_cm: number; breite_cm: number; hoehe_cm: number; bruestung_cm: number; angel: 'anfang' | 'ende'; seite: 1 | -1 }
export interface Raum { id: string; grundriss_id: string; tag_id: string | null; name: string; umriss: [number, number][]; hoehe_cm: number; art: 'raum' | 'balkon'; bodenfarbe: string | null }
export interface Block { x: number; y: number; b: number; t: number; z: number; h: number }
export type EinrichtungArt = 'regal' | 'schrank' | 'moebel' | 'freihalten'
export interface Einrichtung { id: string; grundriss_id: string; raum_id: string; art: EinrichtungArt; name: string; item_id: string | null; x: number; y: number; drehung: 0 | 90 | 180 | 270; bloecke: Block[]; farbe: string | null }
export interface Fach { id: string; einrichtung_id: string; nr: number; name: string; x: number; y: number; b: number; t: number; boden_cm: number; hoehe_cm: number }
export interface PlanKiste { id: string; code: string; status: ItemStatus; kind: ItemKind; room_id: string | null; room_color: string | null; mark_color: string | null; hoehe_cm: number; laenge_cm: number; breite_cm: number; gedreht: boolean; lage: number; unten_cm: number; boden: { raum_id: string; x: number; y: number } | null; fach: { fach_id: string; x: number; y: number } | null }
export interface RaumAnsicht { raum: Raum & { tag_name: string | null; tag_color: string | null }; grundriss: { id: string; name: string; art: GrundrissArt; standard_hoehe_cm: number }; waende: Wand[]; oeffnungen: Oeffnung[]; einrichtung: (Einrichtung & { faecher: Fach[] })[]; kisten: PlanKiste[] }
export interface GrundrissDaten { kopf: GrundrissKopf; waende: Wand[]; oeffnungen: Oeffnung[]; raeume: (Raum & { tag_name: string | null; tag_color: string | null })[]; einrichtung: Einrichtung[]; faecher: Fach[]; kisten: PlanKiste[] }
export type KistenStandort =
  | { art: 'kein_zimmer'; kiste: PlanKiste }
  | { art: 'kein_raum'; kiste: PlanKiste; zimmer: { id: string; name: string } }
  | { art: 'kein_platz'; kiste: PlanKiste; ansicht: RaumAnsicht }
  | { art: 'da'; kiste: PlanKiste; ansicht: RaumAnsicht; hoehe_von: number; hoehe_bis: number; anzahl: number }
export interface Aenderungen<T> { neu: T[]; geaendert: T[]; weg: string[] }
export interface GrundrissAenderung { waende: Aenderungen<Wand>; oeffnungen: Aenderungen<Oeffnung>; raeume: Aenderungen<Raum>; einrichtung: Aenderungen<Einrichtung>; faecher: Aenderungen<Fach> }
export interface OrtErgebnis { item_id: string; lage: number; anzahl: number; hoehe_von: number; hoehe_bis: number }
export interface RaumZuordnung { raum_id: string; grundriss_id: string; tag_id: string | null; name: string }
export type TuerWand = 'oben' | 'rechts' | 'unten' | 'links'
- Item bekommt: ort_raum_id, ort_x_cm, ort_y_cm, fach_id, fach_x_cm, fach_y_cm, ort_lage (alle number|string|null) und ort_gedreht: boolean.
- SuchTreffer wird neu gefasst nach den Spalten von inhalt_finden (siehe datenmodell_sql); plan_x, plan_y, plan_z, regal_name und regal_boden fallen weg.

