TYPEN
type GrundrissArt = 'neu' | 'alt' | 'keller' | 'lager' | 'sonst'
interface Grundriss { id: string; project_id: string; art: GrundrissArt; name: string; wandstaerke_cm: number; sort: number; version: number; created_at: string; updated_at: string }
interface Raum { id: string; grundriss_id: string; project_id: string; tag_id: string | null; name: string; anzeige_name: string; tag_farbe: string | null; tag_short: string | null; aussen: boolean; umriss_cm: number[]; hoehe_cm: number; wandfarben: (string | null)[] | null; flaeche_cm2: number; sort: number }
interface Oeffnung { id: string; raum_id: string; art: 'tuer' | 'fenster'; x0_cm: number; y0_cm: number; x1_cm: number; y1_cm: number; bruestung_cm: number; hoehe_cm: number; aufschlag: 'innen' | 'aussen' | 'keiner'; anschlag: 'links' | 'rechts' }
interface Objekt { id: string; raum_id: string; art: 'regal' | 'schrank' | 'moebel'; name: string; moebel_item_id: string | null; x_cm: number; y_cm: number; drehung: 0 | 90 | 180 | 270; breite_cm: number; tiefe_cm: number; hoehe_cm: number; boden_cm: number; teile_cm: number[] | null; farbe: string | null; teile_abs: number[] }
interface Fach { id: string; objekt_id: string; name: string; links_cm: number; breite_cm: number; boden_cm: number; hoehe_cm: number | null; nr: number; basis_cm: number; grenze_cm: number }
interface KisteImStapel { item_id: string; code: string; prefix: string; size: number; seq: number; title: string | null; status: ItemStatus; kind: ItemKind; mark_color: string | null; tag_farbe: string | null; lage: number; nr: number; l_cm: number; b_cm: number; h_cm: number; drehung: 0 | 90; von_cm: number; bis_cm: number }
interface Stapel { raum_id: string | null; fach_id: string | null; x_cm: number; y_cm: number; w_cm: number; d_cm: number; basis_cm: number; oben_cm: number; grenze_cm: number; kisten: KisteImStapel[] }
interface PlanDaten { grundriss: Grundriss; raeume: Raum[]; oeffnungen: Oeffnung[]; objekte: Objekt[]; faecher: Fach[]; stapel: Stapel[]; hand: { item_id: string; code: string; l_cm: number; b_cm: number; h_cm: number } | null }
type PlatzZiel = { raum_id: string; fach_id?: null; x_cm: number; y_cm: number; drehung: 0 | 90 } | { fach_id: string; raum_id?: null; x_cm: number; y_cm: number; drehung: 0 | 90 }
interface StapelSchluessel { raum_id: string | null; fach_id: string | null; x_cm: number; y_cm: number }
interface KistenOrt { item_id: string; grundriss: Grundriss; raum: Raum; platz: PlatzZiel; objekt: Objekt | null; fach: Fach | null; von_cm: number; bis_cm: number; nr: number; anzahl: number; kontext: PlanDaten }
interface PlatzPruefung { ok: boolean; fehler: string | null; ort: KistenOrt | null }   // fehler bereits übersetzt
interface PlatzStart { kiste: { id: string; code: string; room_id: string | null; l_cm: number; b_cm: number; h_cm: number }; ort: KistenOrt | null; kandidaten: Array<{ grundriss_id: string; grundriss_art: GrundrissArt; grundriss_name: string; raum_id: string; raum_name: string; passt_zum_zimmer: boolean }> }
interface PlanAenderungen {
  grundriss?: { name?: string; art?: GrundrissArt; wandstaerke_cm?: number }
  raeume?: { upsert?: RaumWerte[]; loeschen?: Array<{ id: string; plaetze_raeumen: boolean }>; verschieben?: Array<{ id: string; dx: number; dy: number }> }
  oeffnungen?: { upsert?: OeffnungWerte[]; loeschen?: string[] }
  objekte?: { upsert?: ObjektWerte[]; loeschen?: Array<{ id: string; plaetze_raeumen: boolean }> }
  faecher?: { upsert?: FachWerte[]; loeschen?: string[] }
}
interface UmstellungRest { id: string; project_id: string; item_id: string | null; tag_id: string | null; grund: string; alt: Record<string, unknown>; created_at: string; item_code: string | null }
Item: + eigene_laenge_cm: number | null; eigene_breite_cm: number | null. In E4 fallen plan_x, plan_y, plan_z, regal_id, regal_boden weg.
SuchTreffer: + grundriss_id, grundriss_name, grundriss_art, raum_id, raum_name, raum_farbe, objekt_art, objekt_name, fach_nr, fach_name, platz_x_cm, platz_y_cm, lage_nr, stapel_anzahl. Ohne plan_*, regal_name, regal_boden.

